#!/bin/bash
set -e
# --- sqli_credential_dump ---
export DEBIAN_FRONTEND=noninteractive

# Install runtime
apt-get update -qq
apt-get install -y apache2 php libapache2-mod-php php-mysql php-sqlite3

mkdir -p /var/www/html
# Write index.php
echo '' | base64 -d > /var/www/html/index.php

# Ensure www-data writable dirs
mkdir -p /var/db && chown www-data:www-data /var/db
mkdir -p /var/www/html/uploads && chown www-data:www-data /var/www/html/uploads

# Start application
cd /var/www/html
nohup service apache2 start > /var/log/webapp.log 2>&1 &
sleep 3

# Healthcheck
curl -sf http://localhost/app.php || curl -sf http://localhost/ && echo 'deploy_ok' || echo 'deploy_failed'
